-- Existing records remain in the original owner's garden. The reserved account
-- cannot be claimed through signup; activate it with --set-password.
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT, created_at INTEGER NOT NULL);
CREATE TABLE gardens (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id));
CREATE TABLE garden_members (garden_id TEXT NOT NULL REFERENCES gardens(id), user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(garden_id,user_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), garden_id TEXT NOT NULL REFERENCES gardens(id), expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
