ALTER TABLE plants ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX plants_garden ON plants(garden_id);
ALTER TABLE entries ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX entries_garden ON entries(garden_id);
ALTER TABLE photos ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX photos_garden ON photos(garden_id);
ALTER TABLE readings ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX readings_garden ON readings(garden_id);
ALTER TABLE devices ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX devices_garden ON devices(garden_id);
ALTER TABLE events ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX events_garden ON events(garden_id);
ALTER TABLE seeds ADD garden_id TEXT NOT NULL DEFAULT '00000000-0000-0000-0000-000000000001';
CREATE INDEX seeds_garden ON seeds(garden_id);
CREATE TABLE garden_settings (garden_id TEXT PRIMARY KEY REFERENCES gardens(id), timezone TEXT NOT NULL DEFAULT 'America/Chicago', photo_enabled INTEGER NOT NULL DEFAULT 0, photo_time TEXT NOT NULL DEFAULT '12:00');
INSERT INTO garden_settings(garden_id,timezone,photo_enabled,photo_time) SELECT '00000000-0000-0000-0000-000000000001',timezone,photo_enabled,photo_time FROM settings;
CREATE TRIGGER plants_garden_insert BEFORE INSERT ON plants WHEN NOT EXISTS(SELECT 1 FROM gardens WHERE id=NEW.garden_id) BEGIN SELECT RAISE(ABORT,'Unknown garden'); END;
CREATE TRIGGER plants_garden_update BEFORE UPDATE OF garden_id ON plants WHEN NOT EXISTS(SELECT 1 FROM gardens WHERE id=NEW.garden_id) BEGIN SELECT RAISE(ABORT,'Unknown garden'); END;
